start=$(rg -n '^fn handle_list\(' workflow-tools/session/crates/worktree-ctl/src/main.rs | cut -d: -f1); end=$(( $(rg -n '^fn handle_clean\(' workflow-tools/session/crates/worktree-ctl/src/main.rs | cut -d: -f1) - 1 )); old=$(sed -n "${start},${end}p" workflow-tools/session/crates/worktree-ctl/src/main.rs); count=$(printf '%s\n' "$old" | wc -l); { printf '%s\n' 'diff --git a/crates/worktree-ctl/src/main.rs b/crates/worktree-ctl/src/main.rs' '--- a/crates/worktree-ctl/src/main.rs' '+++ b/crates/worktree-ctl/src/main.rs'; printf '@@ -%s,%s +%s,0 @@\n' "$start" "$count" "$start"; printf '%s\n' "$old" | sed 's/^/-/'; } | git -C workflow-tools/session apply --unidiff-zero --verbose && body=$(cat <<'EOF'
const ANSI_RESET: &str = "\x1b[0m";
const ANSI_RED: &str = "\x1b[31m";
const ANSI_GREEN: &str = "\x1b[32m";
const ANSI_YELLOW: &str = "\x1b[33m";
const ANSI_BLUE: &str = "\x1b[34m";
const ANSI_MAGENTA: &str = "\x1b[35m";
const ANSI_CYAN: &str = "\x1b[36m";

#[derive(Debug)]
struct RepositoryState {
    branch: String,
    dirty: bool,
    ahead: Option<usize>,
    behind: Option<usize>,
}

fn handle_list(_dry_run: bool, verbose: bool) -> Result<(), String> {
    let main_checkout =
        env::current_dir().map_err(|error| error.to_string())?;
    let git =
        WorktreeGit::open(&main_checkout).map_err(|error| error.to_string())?;
    let activity = SessionStoreActivity::with_default_staleness(
        git.main_checkout().join(".session"),
    );
    let policy = ProvisionPolicy::default();
    let registered = git.list_worktrees().map_err(|error| error.to_string())?;

    for worktree in &registered {
        let lifecycle = lifecycle_status(&git, &activity, worktree, &policy)?;
        let superproject = live_repository_state(&git, &worktree.path)?;
        let submodules = live_submodule_states(&git, worktree)?;
        if verbose {
            print_verbose_worktree(&worktree.path, &lifecycle, &superproject, &submodules);
        } else {
            print_compact_worktree(&git, worktree, &lifecycle, &superproject, &submodules);
        }
    }

    let worktree_root = git.main_checkout().join(".worktrees");
    if worktree_root.is_dir() {
        for entry in std::fs::read_dir(&worktree_root)
            .map_err(|error| error.to_string())?
        {
            let entry = entry.map_err(|error| error.to_string())?;
            let path = entry.path();
            if path.is_dir()
                && !registered.iter().any(|worktree| {
                    worktree.path == path || worktree.path.starts_with(&path)
                })
            {
                if verbose {
                    println!("worktree: {}", path.display());
                    println!("  lifecycle: unregistered-debris");
                } else {
                    println!(
                        "{} {} {}",
                        path.strip_prefix(git.main_checkout())
                            .unwrap_or(&path)
                            .display(),
                        color(ANSI_RED, "[debris]"),
                        color(ANSI_RED, "unregistered")
                    );
                }
            }
        }
    }
    Ok(())
}

fn live_submodule_states(
    git: &WorktreeGit,
    worktree: &session_worktree_provision::WorktreeRef,
) -> Result<Vec<(String, Result<RepositoryState, String>)>, String> {
    git.submodule_paths()
        .map_err(|error| error.to_string())?
        .into_iter()
        .map(|submodule| {
            let state = live_repository_state(&git, &worktree.path.join(&submodule));
            Ok((submodule, state))
        })
        .collect()
}

fn print_verbose_worktree(
    path: &Path,
    lifecycle: &str,
    superproject: &RepositoryState,
    submodules: &[(String, Result<RepositoryState, String>)],
) {
    println!("worktree: {}", path.display());
    println!("  lifecycle: {lifecycle}");
    println!("  superproject: {}", verbose_repository_state(superproject));
    if submodules.is_empty() {
        println!("  submodules: none");
    } else {
        println!("  submodules:");
        for (name, state) in submodules {
            match state {
                Ok(state) => println!("    {name}: {}", verbose_repository_state(state)),
                Err(error) => println!("    {name}: unavailable ({error})"),
            }
        }
    }
}

fn print_compact_worktree(
    git: &WorktreeGit,
    worktree: &session_worktree_provision::WorktreeRef,
    lifecycle: &str,
    superproject: &RepositoryState,
    submodules: &[(String, Result<RepositoryState, String>)],
) {
    let relative = worktree
        .path
        .strip_prefix(git.main_checkout())
        .unwrap_or(&worktree.path);
    let expected_branch = worktree_relative_path(git, worktree)
        .ok()
        .and_then(|path| branch_for_relative_path(&path).ok());
    let reason = compact_reason(superproject, submodules);
    let lifecycle = compact_lifecycle(lifecycle);
    let superproject = compact_repository_state(superproject, expected_branch.as_deref());
    let submodules = submodules
        .iter()
        .map(|(name, state)| match state {
            Ok(state) => format!("{name}={}", compact_repository_state(state, None)),
            Err(_) => format!("{name}={}", color(ANSI_RED, "missing")),
        })
        .collect::<Vec<_>>()
        .join(" ");
    println!("{} {} {} :: super={} {}", relative.display(), lifecycle, reason, superproject, submodules);
}

fn color(code: &str, value: impl std::fmt::Display) -> String {
    format!("{code}{value}{ANSI_RESET}")
}

fn compact_lifecycle(lifecycle: &str) -> String {
    if lifecycle == "reclaimable" {
        color(ANSI_GREEN, "[ready]")
    } else if lifecycle.contains("session-active") {
        color(ANSI_CYAN, "[active]")
    } else {
        color(ANSI_YELLOW, "[held]")
    }
}

fn compact_reason(
    superproject: &RepositoryState,
    submodules: &[(String, Result<RepositoryState, String>)],
) -> String {
    let mut dirty = Vec::new();
    let mut ahead = Vec::new();
    let mut behind = Vec::new();
    if superproject.dirty { dirty.push("super".to_owned()); }
    if superproject.ahead.unwrap_or_default() != 0 { ahead.push(format!("super+{}", superproject.ahead.unwrap())); }
    if superproject.behind.unwrap_or_default() != 0 { behind.push(format!("super-{}", superproject.behind.unwrap())); }
    for (name, state) in submodules {
        match state {
            Ok(state) => {
                if state.dirty { dirty.push(name.clone()); }
                if state.ahead.unwrap_or_default() != 0 { ahead.push(format!("{name}+{}", state.ahead.unwrap())); }
                if state.behind.unwrap_or_default() != 0 { behind.push(format!("{name}-{}", state.behind.unwrap())); }
            },
            Err(_) => dirty.push(format!("{name}:missing")),
        }
    }
    let mut parts = Vec::new();
    if !dirty.is_empty() { parts.push(color(ANSI_RED, format!("dirty:{}", dirty.join(",")))); }
    if !ahead.is_empty() { parts.push(color(ANSI_YELLOW, format!("ahead:{}", ahead.join(",")))); }
    if !behind.is_empty() { parts.push(color(ANSI_BLUE, format!("behind:{}", behind.join(",")))); }
    if parts.is_empty() { color(ANSI_GREEN, "clean") } else { parts.join(" ") }
}

fn compact_repository_state(
    state: &RepositoryState,
    expected_branch: Option<&str>,
